    if (state === 'gameover') return '游戏结束';
    return '就绪';
  }

  function syncHud() {
    if (!els) return;
    if (els.score) els.score.textContent = String(score);
    if (els.status) els.status.textContent = statusText();
  }

  function hideOverlay() {
    if (!els) return;
    if (els.overlay) els.overlay.hidden = true;
    if (els.finalScore) els.finalScore.textContent = '0';
  }

  function showOverlay() {
    if (!els) return;
    if (els.finalScore) els.finalScore.textContent = String(score);
    if (els.overlay) els.overlay.hidden = false;
  }

  function spawnFood() {
    var occupied = {};
    var i;
    for (i = 0; i < snake.length; i += 1) {
      occupied[snake[i].x + ',' + snake[i].y] = true;
    }
    var cells = [];
    var x;
    var y;
    for (y = 0; y < ROWS; y += 1) {
      for (x = 0; x < COLS; x += 1) {
        if (!occupied[x + ',' + y]) {
          cells.push({ x: x, y: y });
        }
      }
    }
    if (cells.length === 0) {
      food = null;
      return false;
    }
    food = cells[Math.floor(Math.random() * cells.length)];
    return true;
  }

  function clearTimer() {
    if (timerId !== null) {
      global.clearInterval(timerId);
      timerId = null;
    }
  }

  function startTimer() {
    clearTimer();
    timerId = global.setInterval(step, STEP_MS);
  }

  function resetRound() {
    snake = [
      { x: 10, y: 10 },
      { x: 9, y: 10 },
      { x: 8, y: 10 }
    ];
    direction = RIGHT;
    nextDirection = RIGHT;
    score = 0;
    state = 'ready';
    food = null;
    spawnFood();
    hideOverlay();
    syncHud();
    render();
  }

  function endGame() {
    clearTimer();
    state = 'gameover';
    showOverlay();
    syncHud();
    render();
  }

  function start() {
    if (!initialized) {
      init();
      return;
    }
    if (state !== 'ready') return;
    state = 'running';
    syncHud();
    render();
    startTimer();
  }

  function restart() {
    if (!initialized) {
      init();
      return;
    }
    clearTimer();
    resetRound();
    startTimer();
  }

  function step() {
    if (!initialized || state === 'gameover') return;

    if (state === 'ready') {
      state = 'running';
      syncHud();
    }

    direction = nextDirection;

    var head = snake[0];
    var nx = head.x + direction.x;
    var ny = head.y + direction.y;

    if (nx < 0 || nx >= COLS || ny < 0 || ny >= ROWS) {
      endGame();
      return;
    }

    var eating = Boolean(food) && nx === food.x && ny === food.y;
    var limit = eating ? snake.length : snake.length - 1;
    var i;
    for (i = 0; i < limit; i += 1) {
      if (snake[i].x === nx && snake[i].y === ny) {
        endGame();
        return;
      }
    }

    snake.unshift({ x: nx, y: ny });
    if (eating) {
      score += 1;
      if (!spawnFood()) {
        endGame();
        return;
      }
    } else {
      snake.pop();
    }
    render();
  }

  function onKey(event) {
    if (!event) return;
    var key = typeof event.key === 'string' ? event.key.toLowerCase() : '';

    var dir = null;
    if (key === 'arrowup' || key === 'w') dir = UP;
    else if (key === 'arrowdown' || key === 's') dir = DOWN;
    else if (key === 'arrowleft' || key === 'a') dir = LEFT;
    else if (key === 'arrowright' || key === 'd') dir = RIGHT;

    if (dir) {
      if (event.preventDefault) event.preventDefault();
      if (state === 'gameover') return;
      if (dir.x + direction.x === 0 && dir.y + direction.y === 0) return;
      nextDirection = dir;
      return;
    }

    if (key === ' ' || key === 'spacebar' || key === 'enter') {
      if (state === 'gameover') {
        if (event.preventDefault) event.preventDefault();
        restart();
      }
    }
  }

  function drawGrid(width, height) {
    ctx.save();
    ctx.strokeStyle = 'rgba(148, 163, 184, 0.12)';
    ctx.lineWidth = 1;
    var x;
    var y;
    for (x = 1; x < COLS; x += 1) {
      ctx.beginPath();
      ctx.moveTo(x * CELL + 0.5, 0);
      ctx.lineTo(x * CELL + 0.5, height);
      ctx.stroke();
    }
    for (y = 1; y < ROWS; y += 1) {
      ctx.beginPath();
      ctx.moveTo(0, y * CELL + 0.5);
      ctx.lineTo(width, y * CELL + 0.5);
      ctx.stroke();
    }
    ctx.restore();
  }

  function drawFood() {
    if (!food) return;
    var cx = food.x * CELL + CELL / 2;
    var cy = food.y * CELL + CELL / 2;
    ctx.save();
    ctx.fillStyle = '#f87171';
    ctx.shadowColor = 'rgba(248, 113, 113, 0.65)';
    ctx.shadowBlur = 10;
    ctx.beginPath();
    ctx.arc(cx, cy, CELL * 0.32, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  function drawSnake() {
    var i;
    for (i = snake.length - 1; i >= 0; i -= 1) {
      var seg = snake[i];
      var isHead = i === 0;
      var pad = isHead ? 1 : 2;
      var size = CELL - pad * 2;
      var left = seg.x * CELL + pad;
      var top = seg.y * CELL + pad;
      ctx.save();
      ctx.fillStyle = isHead ? '#4ade80' : '#16a34a';
      ctx.fillRect(left, top, size, size);
      ctx.strokeStyle = 'rgba(2, 6, 23, 0.45)';
      ctx.lineWidth = 1;
      ctx.strokeRect(left + 0.5, top + 0.5, size - 1, size - 1);
      ctx.restore();
    }
  }

  function render() {
    if (!ctx || !els) return;
    var width = els.canvas.width || COLS * CELL;
    var height = els.canvas.height || ROWS * CELL;

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#0b1220';
    ctx.fillRect(0, 0, width, height);

    drawGrid(width, height);
    drawFood();
    drawSnake();

    syncHud();
  }

  function startRenderLoop() {
    if (renderLoopStarted) return;
    renderLoopStarted = true;
    if (typeof global.requestAnimationFrame !== 'function') {
      render();
      return;
    }
    function frame() {
      render();
      global.requestAnimationFrame(frame);
    }
    global.requestAnimationFrame(frame);
  }

  function bindEvents() {
    if (els.restart) {
      els.restart.addEventListener('click', function () {
        restart();
      });
    }
    global.addEventListener('keydown', onKey);
  }

  function init() {
    if (initialized) return;
    if (!cacheElements()) return;
    initialized = true;
    bindEvents();
    restart();
    startRenderLoop();
  }

  global.Game = {
    init: init,
    start: start,
    restart: restart,
    step: step,
    render: render,
    onKey: onKey
  };

  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', init);
    } else {
      init();
    }
  }
})(typeof window !== 'undefined' ? window : this);

input.content:
* {
  box-sizing: border-box;
}

html,
body {
  min-height: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background:
    radial-gradient(circle at 50% 0%, rgba(34, 197, 94, 0.12), transparent 55%),
    radial-gradient(circle at 85% 100%, rgba(56, 189, 248, 0.1), transparent 50%),
    #060b16;
  color: #e2e8f0;
  font-family: "Segoe UI", "PingFang SC", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}

.game-shell {
  width: 440px;
  max-width: 100%;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 20px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 16px;
  background: rgba(15, 23, 42, 0.82);
  box-shadow: 0 24px 60px rgba(2, 6, 23, 0.55);
}

.hud {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.hud__title {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #f1f5f9;
}

.hud__score {
  font-size: 15px;
  color: #94a3b8;
  font-variant-numeric: tabular-nums;
}

#score {
  color: #4ade80;
  font-size: 18px;
  font-weight: 700;
}

.game-stage {
  position: relative;
  width: 400px;
  max-width: 100%;
  aspect-ratio: 1 / 1;
  margin: 0 auto;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  background: #0b1220;
  border: 2px solid rgba(74, 222, 128, 0.35);
  border-radius: 12px;
  box-shadow:
    0 0 0 1px rgba(15, 23, 42, 0.9),
    inset 0 0 40px rgba(2, 6, 23, 0.55);
}

.overlay {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  padding: 24px;
  text-align: center;
  border-radius: 12px;
  background: rgba(2, 6, 23, 0.78);
  -webkit-backdrop-filter: blur(2px);
  backdrop-filter: blur(2px);
}

.overlay[hidden] {
  display: none;
}

.overlay__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #f87171;
}

.overlay__score {
  margin: 0;
  font-size: 15px;
  color: #cbd5e1;
}

#final-score {
  color: #4ade80;
  font-size: 20px;
  font-weight: 700;
}

#restart {
  appearance: none;
  -webkit-appearance: none;
  border: 0;
  padding: 10px 26px;
  border-radius: 999px;
  font-size: 15px;
  font-weight: 700;
  font-family: inherit;
  color: #052e16;
  background: linear-gradient(180deg, #86efac, #22c55e);
  box-shadow: 0 6px 18px rgba(34, 197, 94, 0.35);
  cursor: pointer;
  transition: transform 0.12s ease, box-shadow 0.12s ease;
}

#restart:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 24px rgba(34, 197, 94, 0.45);
}

#restart:active {
  transform: translateY(0);
}

#restart:focus-visible {
  outline: 2px solid #bbf7d0;
  outline-offset: 3px;
}

.status {
  margin: 0;
  text-align: center;
  font-size: 14px;
  color: #94a3b8;
}

.help {
  margin: 0;
  text-align: center;
  font-size: 12px;
  line-height: 1.6;
  color: #64748b;
}

@media (max-width: 480px) {
  body {
    padding: 12px;
  }

  .game-shell {
    padding: 14px;
    gap: 10px;
  }

  .hud__title {
    font-size: 18px;
  }
}

